"""Original QLC tasks. Private references/answers must never be served as public assets."""
TASKS = []
HEADER = '#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\n'
def add(key, lesson, title, statement, input_format, limits, complexity, hints, code, proof, mutation, slow=None, memory=262144, time=1500):
    TASKS.append(dict(key=key, lesson=lesson, title=title, statement=statement,
        input=input_format, limits=limits, complexity=complexity, hints=hints,
        solution=HEADER+code.strip()+'\n', proof=proof, mutation=mutation,
        slow=HEADER+slow.strip()+'\n' if slow else None, memory=memory, time=time))

add('sum',0,'01. Контрольная сумма',
    'Найдите сумму всех чисел в последовательности. Выведите одно целое число.',
    'Первая строка — n. Вторая — n целых чисел a[i].',
    '1 ≤ n ≤ 200000; −10^9 ≤ a[i] ≤ 10^9.',
    'Θ(n) времени, O(1) дополнительной памяти. Чтение входа уже требует Ω(n).',
    ['Сумму можно обновлять сразу при чтении очередного числа.', 'Оцените сумму 200000 чисел по 10^9. Тип int недостаточен.', 'Начните с long long sum = 0 и прибавляйте каждое прочитанное значение.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr); int n;cin>>n;ll sum=0,x;while(n--){cin>>x;sum+=x;}cout<<sum<<"\\n";}',
    'После k прочитанных элементов sum равна сумме первых k элементов: это верно при k=0 и сохраняется прибавлением следующего элемента.',
    ('ll sum=0,x;', 'int sum=0,x;'))

add('increasing-run',0,'02. Полоса роста',
    'Найдите максимальную длину непустого непрерывного строго возрастающего участка массива. Равные соседние элементы прерывают рост. Выведите длину.',
    'Первая строка — n, вторая — массив a из n чисел.',
    '1 ≤ n ≤ 200000; −10^9 ≤ a[i] ≤ 10^9.',
    'Θ(n) времени, O(1) дополнительной памяти.',
    ['Достаточно сравнивать текущее число с предыдущим.', 'Храните длину возрастающего участка, который заканчивается именно сейчас.', 'Если prev < x, увеличьте длину; иначе начните участок длины 1. Обновляйте максимум на каждом шаге.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,cur=0,ans=0;cin>>n;ll prev=0,x;for(int i=0;i<n;i++){cin>>x;cur=(i>0 && prev<x)?cur+1:1;ans=max(ans,cur);prev=x;}cout<<ans<<"\\n";}',
    'Любой возрастающий участок, заканчивающийся в i, продолжает участок в i−1, если a[i−1]<a[i]; иначе содержит только a[i]. Максимум по всем окончаниям перебирает все кандидаты.',
    ('prev<x','prev<=x'),
    'int main(){int n;cin>>n;vector<ll>a(n);for(auto &x:a)cin>>x;int ans=1;for(int i=0;i<n;i++){int j=i;while(j+1<n&&a[j]<a[j+1])j++;ans=max(ans,j-i+1);}cout<<ans<<"\\n";}')

add('range-sum',1,'03. Архив измерений',
    'Для каждого запроса l, r найдите сумму a[l] + … + a[r]. Массив не меняется. Печатайте ответ на каждый запрос в отдельной строке.',
    'n q; затем n чисел массива; затем q строк l r. Индексы начинаются с 1.',
    '1 ≤ n,q ≤ 200000; −10^9 ≤ a[i] ≤ 10^9; 1 ≤ l ≤ r ≤ n.',
    'Θ(n+q) времени, O(n) памяти. Запрос после подготовки — O(1).',
    ['Много запросов повторно складывают одни и те же элементы.', 'Обозначьте p[i] суммой первых i чисел и добавьте p[0]=0.', 'Ответ для включённого отрезка [l,r] равен p[r]−p[l−1]. Храните суммы в long long.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,q;cin>>n>>q;vector<ll>p(n+1);for(int i=1;i<=n;i++){ll x;cin>>x;p[i]=p[i-1]+x;}while(q--){int l,r;cin>>l>>r;cout<<p[r]-p[l-1]<<"\\n";}}',
    'Префикс до r содержит искомый отрезок и первые l−1 элементов. Вычитание последнего префикса оставляет каждый элемент отрезка ровно один раз.',
    ('p[r]-p[l-1]','p[r]-p[l]'),
    'int main(){int n,q;cin>>n>>q;vector<ll>a(n);for(auto&x:a)cin>>x;while(q--){int l,r;cin>>l>>r;ll s=0;for(int i=l-1;i<r;i++)s+=a[i];cout<<s<<"\\n";}}')

add('range-add',1,'04. Пакет изменений',
    'Изначально массив из n чисел заполнен нулями. Каждая операция l r x прибавляет x ко всем элементам с l по r включительно. Выполните все операции, затем выведите итоговые элементы по одному в строке.',
    'n q; далее q строк l r x. Индексы с 1.',
    '1 ≤ n,q ≤ 200000; 1 ≤ l ≤ r ≤ n; −10^9 ≤ x ≤ 10^9.',
    'Θ(n+q) времени, O(n) памяти.',
    ['Ответы нужны только после всех изменений.', 'Отметьте начало и конец действия прибавления в разностном массиве.', 'Сделайте d[l]+=x, d[r+1]−=x. Префиксная сумма d восстанавливает итоговый массив.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,q;cin>>n>>q;vector<ll>d(n+2);while(q--){int l,r;ll x;cin>>l>>r>>x;d[l]+=x;d[r+1]-=x;}ll s=0;for(int i=1;i<=n;i++){s+=d[i];cout<<s<<"\\n";}}',
    'В префикс для i попадёт +x ровно при i≥l, а −x при i≥r+1. Поэтому вклад операции равен x только внутри [l,r].',
    ('d[r+1]-=x','d[r]-=x'),
    'int main(){int n,q;cin>>n>>q;vector<ll>a(n);while(q--){int l,r;ll x;cin>>l>>r>>x;for(int i=l-1;i<r;i++)a[i]+=x;}for(ll x:a)cout<<x<<"\\n";}')

add('inversions',2,'05. Цена перестановки',
    'Посчитайте пары индексов i < j, для которых a[i] > a[j]. Равные элементы инверсии не образуют. Выведите число пар.',
    'n; затем n целых чисел массива.',
    '1 ≤ n ≤ 200000; −10^9 ≤ a[i] ≤ 10^9.',
    'O(n log n) времени, O(n) дополнительной памяти. Это стандартная эффективная оценка для произвольных сравнимых значений.',
    ['Разделите пары на лежащие в левой половине, правой и пересекающие границу.', 'При слиянии отсортированных половин справа можно взять элемент раньше оставшихся слева.', 'Если a[i]>a[j], этот правый элемент образует инверсии со всеми m−i оставшимися элементами слева. При равенстве берите слева.'],
    '''vector<ll>a,b;ll solve(int l,int r){if(r-l<2)return 0;int m=(l+r)/2;ll ans=solve(l,m)+solve(m,r);int i=l,j=m,k=l;while(i<m||j<r){if(j==r||(i<m&&a[i]<=a[j]))b[k++]=a[i++];else{ans+=m-i;b[k++]=a[j++];}}copy(b.begin()+l,b.begin()+r,a.begin()+l);return ans;}
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n;cin>>n;a.resize(n);b.resize(n);for(auto&x:a)cin>>x;cout<<solve(0,n)<<"\\n";}''',
    'Пары внутри половин считаются рекурсивно. При выборе меньшего правого элемента ровно все ещё не перенесённые левые элементы больше него. Ни одна перекрёстная пара не учитывается дважды.',
    ('a[i]<=a[j]','a[i]<a[j]'),
    'int main(){int n;cin>>n;vector<ll>a(n);for(auto&x:a)cin>>x;ll z=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)z+=a[i]>a[j];cout<<z<<"\\n";}')

add('union-length',2,'06. Занятая полоса',
    'Даны полуинтервалы [l,r) на числовой прямой. Найдите длину их объединения: каждую покрытую точку учитывайте один раз. Выведите целое число.',
    'n; затем n строк l r.',
    '1 ≤ n ≤ 200000; −10^9 ≤ l < r ≤ 10^9.',
    'O(n log n) времени на сортировку, O(n) памяти для входа.',
    ['После сортировки по левой границе пересекающиеся отрезки оказываются рядом.', 'Поддерживайте текущий объединённый полуинтервал [L,R).', 'Если l≤R, увеличьте R до max(R,r). Иначе прибавьте R−L к ответу и начните новый интервал. После цикла добавьте последний.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n;cin>>n;vector<pair<ll,ll>>a(n);for(auto&[l,r]:a)cin>>l>>r;sort(a.begin(),a.end());ll L=a[0].first,R=a[0].second,ans=0;for(auto[l,r]:a){if(l<=R)R=max(R,r);else{ans+=R-L;L=l;R=r;}}cout<<ans+R-L<<"\\n";}',
    'При l>R ни один последующий отрезок уже не соединится с текущим блоком: их начала не меньше l. Пересекающийся отрезок меняет только правую границу блока.',
    ('R=max(R,r)','R=r'),
    'int main(){int n;cin>>n;vector<pair<ll,ll>>a(n);vector<ll>x;for(auto&[l,r]:a){cin>>l>>r;x.push_back(l);x.push_back(r);}sort(x.begin(),x.end());ll ans=0;for(int i=1;i<(int)x.size();i++){bool on=false;for(auto[l,r]:a)if(l<=x[i-1]&&r>=x[i])on=true;if(on)ans+=x[i]-x[i-1];}cout<<ans<<"\\n";}')

add('capacity',3,'07. Доставка по дням',
    'Грузы идут в заданном порядке. Разбейте последовательность на не более k непустых непрерывных групп. Минимизируйте максимальную сумму одной группы. Выведите этот минимум.',
    'n k; затем n положительных весов.',
    '1 ≤ k ≤ n ≤ 200000; 1 ≤ a[i] ≤ 10^9.',
    'O(n log(sum a)) времени, O(n) памяти.',
    ['Проверьте более простой вопрос: хватит ли грузоподъёмности C?', 'Для фиксированного C заполняйте текущий день до тех пор, пока следующий груз помещается.', 'Проверка монотонна. Ищите первую допустимую C от max(a) до sum(a); суммы и границы — long long.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,k;cin>>n>>k;vector<ll>a(n);ll lo=0,hi=0;for(auto&x:a){cin>>x;lo=max(lo,x);hi+=x;}while(lo<hi){ll mid=lo+(hi-lo)/2,s=0;int groups=1;for(ll x:a){if(s+x>mid){groups++;s=0;}s+=x;}if(groups<=k)hi=mid;else lo=mid+1;}cout<<lo<<"\\n";}',
    'Жадная группа при заданной ёмкости заканчивается не раньше первой группы любого допустимого разбиения. Повторение аргумента минимизирует количество групп. Увеличение ёмкости не ухудшает допустимость.',
    ('groups<=k','groups<k'),
    'int main(){int n,k;cin>>n>>k;vector<ll>a(n);ll lo=0,hi=0;for(auto&x:a){cin>>x;lo=max(lo,x);hi+=x;}for(ll c=lo;c<=hi;c++){ll s=0;int z=1;for(ll x:a){if(s+x>c){z++;s=0;}s+=x;}if(z<=k){cout<<c<<"\\n";return 0;}}}')

add('spacing',3,'08. Расстановка станций',
    'Выберите k из n заданных различных координат. Максимизируйте минимальное расстояние между соседними выбранными точками. Выведите расстояние.',
    'n k; затем n координат в произвольном порядке.',
    '2 ≤ k ≤ n ≤ 200000; −10^9 ≤ x[i] ≤ 10^9; координаты различны.',
    'O(n log n + n log D) времени, O(n) памяти, D=max(x)−min(x).',
    ['Отсортируйте точки и проверяйте возможность расстояния d.', 'Первую станцию ставьте в самой левой точке, каждую следующую — в первой допустимой.', 'Ищите последнее допустимое d. Удобны lo=0 (допустимо) и hi=max−min+1 (недопустимо).'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,k;cin>>n>>k;vector<ll>a(n);for(auto&x:a)cin>>x;sort(a.begin(),a.end());ll lo=0,hi=a.back()-a[0]+1;while(hi-lo>1){ll d=(lo+hi)/2,last=a[0];int cnt=1;for(int i=1;i<n;i++)if(a[i]-last>=d){cnt++;last=a[i];}if(cnt>=k)lo=d;else hi=d;}cout<<lo<<"\\n";}',
    'Замена первой станции любой допустимой расстановки самой левой не мешает последующим. То же верно для каждого следующего самого раннего допустимого выбора.',
    ('a[i]-last>=d','a[i]-last>d'),
    'int main(){int n,k;cin>>n>>k;vector<ll>a(n);for(auto&x:a)cin>>x;sort(a.begin(),a.end());ll ans=0;for(ll d=1;d<=a.back()-a[0];d++){int c=1;ll last=a[0];for(int i=1;i<n;i++)if(a[i]-last>=d){c++;last=a[i];}if(c<k)break;ans=d;}cout<<ans<<"\\n";}')

add('short-window',4,'09. Короткий запас',
    'Найдите длину кратчайшего непустого непрерывного участка с суммой не меньше S. Если такого участка нет, выведите 0.',
    'n S; затем n положительных чисел.',
    '1 ≤ n ≤ 200000; 1 ≤ a[i] ≤ 10^9; 1 ≤ S ≤ 10^18.',
    'Θ(n) времени, O(n) памяти для массива.',
    ['Из-за положительности добавление справа увеличивает сумму, удаление слева уменьшает.', 'Двигайте правую границу и, пока сумма достаточна, сжимайте окно слева.', 'Обновляйте ответ до удаления левого элемента. Каждый указатель проходит массив один раз.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n;ll S;cin>>n>>S;vector<ll>a(n);for(auto&x:a)cin>>x;ll sum=0;int l=0,ans=n+1;for(int r=0;r<n;r++){sum+=a[r];while(sum>=S){ans=min(ans,r-l+1);sum-=a[l++];}}cout<<(ans==n+1?0:ans)<<"\\n";}',
    'Для каждого правого конца цикл проверяет самые короткие допустимые окна. Уже удалённая левая граница для более позднего правого конца даст только более длинный участок, поэтому её возврат не нужен.',
    ('sum>=S','sum>S'),
    'int main(){int n;ll S;cin>>n>>S;vector<ll>a(n);for(auto&x:a)cin>>x;int z=n+1;for(int i=0;i<n;i++){ll s=0;for(int j=i;j<n;j++){s+=a[j];if(s>=S)z=min(z,j-i+1);}}cout<<(z==n+1?0:z)<<"\\n";}')

add('close-pairs',4,'10. Близкие показания',
    'Посчитайте пары различных индексов i<j, для которых |a[i]−a[j]|≤K. Одинаковые значения на разных позициях образуют разные пары.',
    'n K; затем n чисел.',
    '1 ≤ n ≤ 200000; 0 ≤ K ≤ 2000000000; −10^9 ≤ a[i] ≤ 10^9.',
    'O(n log n) времени с сортировкой, O(n) памяти.',
    ['Порядок исходных индексов не влияет на число неупорядоченных пар.', 'После сортировки подходящие левые партнёры каждого a[r] образуют непрерывный участок.', 'Сдвигайте l, пока a[r]−a[l]>K. Прибавляйте r−l; ответ может превышать int.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n;ll K;cin>>n>>K;vector<ll>a(n);for(auto&x:a)cin>>x;sort(a.begin(),a.end());ll ans=0;int l=0;for(int r=0;r<n;r++){while(a[r]-a[l]>K)l++;ans+=r-l;}cout<<ans<<"\\n";}',
    'Каждая пара учитывается ровно в момент обработки большего по позиции элемента отсортированного массива. Монотонность значений позволяет удалять неподходящих партнёров навсегда.',
    ('ans+=r-l','ans+=r-l+1'),
    'int main(){int n;ll K;cin>>n>>K;vector<ll>a(n);for(auto&x:a)cin>>x;ll z=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)z+=abs(a[i]-a[j])<=K;cout<<z<<"\\n";}')

add('next-smaller',5,'11. Ближайший спад',
    'Для каждой позиции найдите индекс первого строго меньшего элемента справа. Если его нет, ответ −1. Печатайте n ответов, каждый в отдельной строке.',
    'n; затем n чисел. Индексы с 1.',
    '1 ≤ n ≤ 200000; −10^9 ≤ a[i] ≤ 10^9.',
    'Θ(n) времени, O(n) памяти.',
    ['Просматривайте элементы справа налево и храните кандидатов.', 'Кандидат не меньше текущего элемента никогда не понадобится позициям слева: текущий ближе и не больше.', 'Удалите из стека индексы с a[top]≥a[i]. Оставшаяся вершина — ответ; затем положите i.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n;cin>>n;vector<ll>a(n);for(auto&x:a)cin>>x;vector<int>s,ans(n,-1);for(int i=n-1;i>=0;i--){while(!s.empty()&&a[s.back()]>=a[i])s.pop_back();if(!s.empty())ans[i]=s.back()+1;s.push_back(i);}for(int x:ans)cout<<x<<"\\n";}',
    'Удалённый кандидат доминируется текущим: для любого элемента слева текущий ближе и не больше. Стек сохраняет порядок индексов и строго возрастающие значения от основания стека к вершине.',
    ('a[s.back()]>=a[i]','a[s.back()]>a[i]'),
    'int main(){int n;cin>>n;vector<ll>a(n);for(auto&x:a)cin>>x;for(int i=0;i<n;i++){int ans=-1;for(int j=i+1;j<n;j++)if(a[j]<a[i]){ans=j+1;break;}cout<<ans<<"\\n";}}')

add('window-min',5,'12. Минимум в движении',
    'Для каждого непрерывного окна длины k выведите минимальный элемент. Окна рассматриваются слева направо, каждый ответ с новой строки.',
    'n k; затем n чисел.',
    '1 ≤ k ≤ n ≤ 200000; −10^9 ≤ a[i] ≤ 10^9.',
    'Θ(n) времени, O(k) дополнительной памяти помимо входа; эталон читает поток.',
    ['Нужно удалять как устаревшие элементы, так и заведомо бесполезные кандидаты.', 'Храните в деке индексы и значения; значения должны возрастать от начала к концу.', 'Спереди удалите индексы ≤i−k; сзади — значения ≥нового. Минимум окна находится спереди.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,k;cin>>n>>k;deque<pair<int,ll>>d;for(int i=0;i<n;i++){ll x;cin>>x;while(!d.empty()&&d.front().first<=i-k)d.pop_front();while(!d.empty()&&d.back().second>=x)d.pop_back();d.push_back({i,x});if(i>=k-1)cout<<d.front().second<<"\\n";}}',
    'Более новый элемент не больше старого и покинет окно позже, поэтому старый можно удалить. Каждый индекс добавляется и удаляется не более одного раза — это амортизированный, а не квадратичный анализ.',
    ('d.front().first<=i-k','d.front().first<i-k'),
    'int main(){int n,k;cin>>n>>k;vector<ll>a(n);for(auto&x:a)cin>>x;for(int i=0;i+k<=n;i++){ll z=a[i];for(int j=i;j<i+k;j++)z=min(z,a[j]);cout<<z<<"\\n";}}')
add('merge-cost',6,'13. Слияние архивов',
    'За одну операцию можно объединить два архива размеров x и y, заплатив x+y; новый архив имеет размер x+y. Найдите минимальную суммарную стоимость объединения всех архивов в один.',
    'n; затем n размеров.', '1 ≤ n ≤ 200000; 1 ≤ a[i] ≤ 10^9.',
    'O(n log n) времени, O(n) памяти.',
    ['Каждый архив оплачивается столько раз, сколько слияний с его участием произойдёт.', 'Выгодно раньше соединять два самых маленьких текущих архива.', 'Храните размеры в min-heap. Извлекайте два минимума, добавляйте сумму в ответ и возвращайте её в кучу.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n;cin>>n;priority_queue<ll,vector<ll>,greater<ll>>q;while(n--){ll x;cin>>x;q.push(x);}ll ans=0;while(q.size()>1){ll a=q.top();q.pop();ll b=q.top();q.pop();ans+=a+b;q.push(a+b);}cout<<ans<<"\\n";}',
    'Дерево слияний имеет стоимость Σ(size[i]·depth[i]). Два наименьших веса можно обменами поместить в пару самых глубоких листьев без увеличения стоимости. Сжав эту пару, получаем меньшую задачу того же вида.',
    ('greater<ll>','less<ll>'),
    'int main(){int n;cin>>n;vector<ll>a(n);for(auto&x:a)cin>>x;ll z=0;while(a.size()>1){sort(a.begin(),a.end());ll s=a[0]+a[1];z+=s;a.erase(a.begin(),a.begin()+2);a.push_back(s);}cout<<z<<"\\n";}')

add('ordered-set',6,'14. Ближайший свободный номер',
    'Поддерживайте множество целых чисел. Операции: `+ x` добавляет x; `- x` удаляет x, если он есть; `? x` запрашивает минимальный элемент не меньше x. Повторное добавление ничего не меняет. Для каждого запроса выведите число либо слово NONE.',
    'q; далее q строк с символом операции и числом x. Множество изначально пусто.',
    '1 ≤ q ≤ 200000; −10^9 ≤ x ≤ 10^9; есть хотя бы один запрос ?.',
    'O(q log q) времени, O(q) памяти; сбалансированное дерево поиска.',
    ['Запрос требует порядка, а не только проверки наличия.', 'В std::set поиск первого элемента ≥x выполняет lower_bound(x).', 'Проверьте результат на end(). Дубликаты не увеличивают множество, удаление отсутствующего элемента допустимо.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int q;cin>>q;set<ll>s;while(q--){char op;ll x;cin>>op>>x;if(op==\'+\')s.insert(x);else if(op==\'-\')s.erase(x);else{auto it=s.lower_bound(x);if(it==s.end())cout<<"NONE\\n";else cout<<*it<<"\\n";}}}',
    'Инвариант: дерево содержит ровно элементы, добавленные и не удалённые последующими операциями. lower_bound возвращает первую позицию, на которой предикат value<x перестаёт выполняться.',
    ('s.lower_bound(x)','s.upper_bound(x)'),
    'int main(){int q;cin>>q;unordered_set<ll>s;while(q--){char op;ll x;cin>>op>>x;if(op==\'+\')s.insert(x);else if(op==\'-\')s.erase(x);else{ll z=LLONG_MAX;for(ll v:s)if(v>=x)z=min(z,v);if(z==LLONG_MAX)cout<<"NONE\\n";else cout<<z<<"\\n";}}}')

add('interval-choice',7,'15. Один переговорный зал',
    'Выберите максимальное число встреч [l,r), которые не пересекаются. Встреча, начинающаяся ровно в момент окончания предыдущей, допустима. Выведите количество.',
    'n; затем n строк l r.', '1 ≤ n ≤ 200000; −10^9 ≤ l < r ≤ 10^9.',
    'O(n log n) времени, O(n) памяти.',
    ['Самая ранняя по началу или самая короткая встреча не всегда оптимальна.', 'Среди доступных встреч выбирайте ту, которая заканчивается раньше всех.', 'Сортируйте по r и берите встречу, когда l≥конца последней выбранной. Начальное значение конца должно быть меньше любой координаты.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n;cin>>n;vector<pair<ll,ll>>a(n);for(auto&[r,l]:a)cin>>l>>r;sort(a.begin(),a.end());ll last=LLONG_MIN;int ans=0;for(auto[r,l]:a)if(l>=last){ans++;last=r;}cout<<ans<<"\\n";}',
    'Первую встречу оптимального расписания можно заменить самой ранней по окончанию: она освобождает зал не позже. После замены остаётся такая же задача для встреч, начинающихся после её конца.',
    ('l>=last','l>last'),
    'int main(){int n;cin>>n;vector<pair<ll,ll>>a(n);for(auto&[l,r]:a)cin>>l>>r;ll last=LLONG_MIN;int ans=0;while(true){ll best=LLONG_MAX;for(auto[l,r]:a)if(l>=last)best=min(best,r);if(best==LLONG_MAX)break;last=best;ans++;}cout<<ans<<"\\n";}')

add('subarray-target',7,'16. Точный баланс',
    'Посчитайте непустые непрерывные участки массива с суммой ровно K. Числа могут быть отрицательными. Выведите количество участков.',
    'n K; затем n чисел.', '1 ≤ n ≤ 200000; −10^9 ≤ a[i] ≤ 10^9; |K| ≤ 10^14.',
    'O(n log n) гарантированного времени, O(n) памяти с map. Хеш-таблица даёт ожидаемое O(n), но без гарантии на худший случай.',
    ['Два указателя с отрицательными числами теряют монотонность.', 'Сумма участка равна разности двух префиксов. Для текущего p нужен предыдущий префикс p−K.', 'Храните частоты уже встреченных префиксов; начните с частоты 0, равной 1. Сначала добавьте freq[p−K] к ответу, затем увеличьте freq[p].'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n;ll k;cin>>n>>k;map<ll,ll>f;f[0]=1;ll p=0,ans=0;while(n--){ll x;cin>>x;p+=x;auto it=f.find(p-k);if(it!=f.end())ans+=it->second;f[p]++;}cout<<ans<<"\\n";}',
    'При обработке правого конца карта содержит каждый допустимый левый префикс с его кратностью. Обновление после подсчёта не допускает пустого участка.',
    ('f[0]=1','f[0]=0'),
    'int main(){int n;ll k;cin>>n>>k;vector<ll>a(n);for(auto&x:a)cin>>x;ll z=0;for(int i=0;i<n;i++){ll s=0;for(int j=i;j<n;j++){s+=a[j];z+=s==k;}}cout<<z<<"\\n";}')

add('coins',8,'17. Неразменный запас',
    'Доступны монеты заданных положительных номиналов в неограниченном количестве. Найдите минимальное число монет для суммы S. Если сумму собрать нельзя, выведите −1.',
    'n S; затем n номиналов. Номиналы могут повторяться.',
    '1 ≤ n ≤ 100; 0 ≤ S ≤ 100000; 1 ≤ c[i] ≤ 100000.',
    'O(nS) времени, O(S) памяти — псевдополиномиальное ДП по сумме.',
    ['Жадный выбор самой крупной монеты ломается, например, на номиналах 1,3,4 и сумме 6.', 'dp[s] — минимум монет для точной суммы s; dp[0]=0, недостижимые состояния — INF.', 'Перебирайте суммы по возрастанию: dp[s]=min(dp[s−c]+1) по c≤s.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,S;cin>>n>>S;vector<int>c(n),dp(S+1,S+1);for(auto&x:c)cin>>x;dp[0]=0;for(int s=1;s<=S;s++)for(int x:c)if(x<=s)dp[s]=min(dp[s],dp[s-x]+1);cout<<(dp[S]>S?-1:dp[S])<<"\\n";}',
    'В любом непустом решении есть последняя монета c. Удалив её, получаем оптимально решаемую меньшую сумму; все возможные последние монеты перечислены.',
    ('dp[0]=0','dp[0]=1'),
    'vector<int>c;int f(int s){if(s==0)return 0;int z=1000000;for(int x:c)if(x<=s)z=min(z,1+f(s-x));return z;}int main(){int n,S;cin>>n>>S;c.resize(n);for(auto&x:c)cin>>x;int z=f(S);cout<<(z>=1000000?-1:z)<<"\\n";}')

add('lis',8,'18. Растущая подпоследовательность',
    'Найдите длину наибольшей строго возрастающей подпоследовательности. Выбранные элементы должны сохранять исходный порядок, но не обязаны идти подряд.',
    'n; затем n целых чисел.', '1 ≤ n ≤ 200000; −10^9 ≤ a[i] ≤ 10^9.',
    'O(n log n) времени, O(L) памяти, L — длина ответа.',
    ['Для одной длины выгодно хранить минимально возможный последний элемент.', 'tails[len−1] — минимальный хвост возрастающей подпоследовательности длины len.', 'Найдите lower_bound(x), замените найденный хвост на x или добавьте x в конец. Для строгого роста нужен lower_bound, а не upper_bound.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n;cin>>n;vector<ll>t;while(n--){ll x;cin>>x;auto it=lower_bound(t.begin(),t.end(),x);if(it==t.end())t.push_back(x);else *it=x;}cout<<t.size()<<"\\n";}',
    'Меньший хвост никогда не ухудшает возможность продолжения. Позиция первого хвоста ≥x показывает ровно ту длину, хвост которой можно улучшить текущим элементом.',
    ('lower_bound(t.begin(),t.end(),x)','upper_bound(t.begin(),t.end(),x)'),
    'int main(){int n;cin>>n;vector<ll>a(n);vector<int>d(n,1);for(auto&x:a)cin>>x;int z=1;for(int i=0;i<n;i++){for(int j=0;j<i;j++)if(a[j]<a[i])d[i]=max(d[i],d[j]+1);z=max(z,d[i]);}cout<<z<<"\\n";}')

add('knapsack',9,'19. Экспедиционный рюкзак',
    'Каждый из n предметов можно взять не более одного раза. Его вес w и ценность v известны. Максимизируйте суммарную ценность при весе не больше W. Можно не брать ничего.',
    'n W; затем n строк w v.', '1 ≤ n ≤ 100; 0 ≤ W ≤ 100000; 1 ≤ w ≤ 100000; 0 ≤ v ≤ 10^9.',
    'O(nW) времени, O(W) памяти.',
    ['Отношение ценности к весу не решает неделимый рюкзак.', 'dp[c] хранит лучшую ценность при вместимости c после уже обработанных предметов.', 'Для одного предмета перебирайте c от W к w: dp[c]=max(dp[c],dp[c−w]+v). Возрастание позволило бы брать предмет много раз.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,W;cin>>n>>W;vector<ll>d(W+1);while(n--){int w;ll v;cin>>w>>v;for(int c=W;c>=w;c--)d[c]=max(d[c],d[c-w]+v);}cout<<d[W]<<"\\n";}',
    'Оптимум либо не содержит текущий предмет, либо содержит его один раз и оптимальный набор предыдущих предметов для c−w. Обратный порядок сохраняет значения предыдущего слоя.',
    ('for(int c=W;c>=w;c--)','for(int c=w;c<=W;c++)'),
    'vector<int>w;vector<ll>v;ll f(int i,int c){if(i==(int)w.size())return 0;ll z=f(i+1,c);if(w[i]<=c)z=max(z,v[i]+f(i+1,c-w[i]));return z;}int main(){int n,W;cin>>n>>W;w.resize(n);v.resize(n);for(int i=0;i<n;i++)cin>>w[i]>>v[i];cout<<f(0,W)<<"\\n";}')

add('edit-distance',9,'20. Редактор команд',
    'Найдите минимальное число вставок, удалений и замен одного символа для превращения строки a в b. Каждая операция стоит 1; перестановка соседних символов отдельной операцией не является.',
    'Две строки a и b в отдельных строках; обе непусты, содержат только a…z.',
    '1 ≤ |a|,|b| ≤ 3000.',
    'O(|a|·|b|) времени, O(min(|a|,|b|)) памяти для двух строк ДП.',
    ['Рассмотрите задачу для двух префиксов.', 'Последняя операция удаляет, вставляет или совмещает два последних символа.', 'dp[i][j]=min(dp[i−1][j]+1,dp[i][j−1]+1,dp[i−1][j−1]+(a[i−1]!=b[j−1])). Достаточно двух строк.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);string a,b;cin>>a>>b;if(a.size()<b.size())swap(a,b);int m=b.size();vector<int>p(m+1),d(m+1);iota(p.begin(),p.end(),0);for(int i=1;i<=(int)a.size();i++){d[0]=i;for(int j=1;j<=m;j++)d[j]=min({p[j]+1,d[j-1]+1,p[j-1]+(a[i-1]!=b[j-1])});swap(p,d);}cout<<p[m]<<"\\n";}',
    'Любое выравнивание префиксов заканчивается одним из трёх перечисленных действий. База dp[0][j]=j и dp[i][0]=i соответствует удалению или вставке всего префикса.',
    ('p[j-1]+(a[i-1]!=b[j-1])','p[j-1]+1'),
    'string a,b;int f(int i,int j){if(i==0)return j;if(j==0)return i;return min({f(i-1,j)+1,f(i,j-1)+1,f(i-1,j-1)+(a[i-1]!=b[j-1])});}int main(){cin>>a>>b;cout<<f(a.size(),b.size())<<"\\n";}')

add('bfs',10,'21. Число пересадок',
    'В неориентированном невзвешенном графе найдите расстояние от вершины s до каждой вершины. Расстояние — число рёбер; для недостижимой вершины выведите −1. Ответы в порядке вершин 1…n, каждый с новой строки.',
    'n m s; затем m строк u v. Возможны петли и повторяющиеся рёбра.',
    '1 ≤ n ≤ 200000; 0 ≤ m ≤ 300000; 1 ≤ s,u,v ≤ n.',
    'Θ(n+m) времени, O(n+m) памяти.',
    ['Все рёбра стоят одинаково: вершины можно открывать по слоям расстояния.', 'Используйте очередь, а не стек. Помечайте вершину при добавлении в очередь.', 'd[s]=0; для ещё не посещённого соседа v положите d[v]=d[u]+1. Недостижимые расстояния оставьте −1.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m,s;cin>>n>>m>>s;vector<vector<int>>g(n+1);while(m--){int u,v;cin>>u>>v;g[u].push_back(v);g[v].push_back(u);}vector<int>d(n+1,-1);queue<int>q;d[s]=0;q.push(s);while(!q.empty()){int u=q.front();q.pop();for(int v:g[u])if(d[v]==-1){d[v]=d[u]+1;q.push(v);}}for(int i=1;i<=n;i++)cout<<d[i]<<"\\n";}',
    'Очередь обрабатывает вершины в неубывающем порядке расстояния. Первый путь к новой вершине имеет минимальную возможную длину: все более короткие предшественники уже обработаны.',
    ('d[v]=d[u]+1','d[v]=d[u]+2'),
    'int main(){int n,m,s;cin>>n>>m>>s;vector<pair<int,int>>e(m);for(auto&[u,v]:e)cin>>u>>v;vector<int>d(n+1,1000000000);d[s]=0;for(int i=1;i<n;i++)for(auto[u,v]:e){d[v]=min(d[v],d[u]+1);d[u]=min(d[u],d[v]+1);}for(int i=1;i<=n;i++)cout<<(d[i]==1000000000?-1:d[i])<<"\\n";}')

add('bipartite',10,'22. Два канала',
    'Можно ли раскрасить все вершины неориентированного графа в два цвета так, чтобы концы каждого ребра имели разные цвета? Выведите YES или NO. Граф может быть несвязным.',
    'n m; затем m строк u v. Петли и повторяющиеся рёбра разрешены.',
    '1 ≤ n ≤ 200000; 0 ≤ m ≤ 300000; 1 ≤ u,v ≤ n.',
    'Θ(n+m) времени, O(n+m) памяти.',
    ['Начинайте отдельный обход в каждой ещё не окрашенной компоненте.', 'Сосед должен получить противоположный цвет.', 'Если оба конца ребра уже одного цвета, ответ NO. Петля сразу создаёт такой конфликт.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m;cin>>n>>m;vector<vector<int>>g(n);while(m--){int u,v;cin>>u>>v;--u;--v;g[u].push_back(v);g[v].push_back(u);}vector<int>c(n,-1);for(int s=0;s<n;s++)if(c[s]<0){queue<int>q;q.push(s);c[s]=0;while(!q.empty()){int u=q.front();q.pop();for(int v:g[u]){if(c[v]==c[u]){cout<<"NO\\n";return 0;}if(c[v]<0){c[v]=c[u]^1;q.push(v);}}}}cout<<"YES\\n";}',
    'Обход задаёт цвет по чётности длины пути в дереве обхода. Конфликт означает нечётный замкнутый маршрут и невозможность двух цветов; без конфликтов все рёбра проверены.',
    ('for(int s=0;s<n;s++)','for(int s=0;s<1;s++)'),
    'int n;vector<pair<int,int>>e;vector<int>c;bool f(int i){if(i==n){for(auto[u,v]:e)if(c[u]==c[v])return false;return true;}c[i]=0;if(f(i+1))return true;c[i]=1;return f(i+1);}int main(){int m;cin>>n>>m;e.resize(m);c.resize(n);for(auto&[u,v]:e){cin>>u>>v;--u;--v;}cout<<(f(0)?"YES":"NO")<<"\\n";}')
add('dag-longest',11,'23. Цепочка зависимостей',
    'Дан ориентированный граф. Если в нём есть цикл, выведите −1. Иначе найдите максимальное число рёбер в пути; путь из одной вершины имеет длину 0.',
    'n m; затем m ориентированных рёбер u v. Возможны петли и повторения.',
    '1 ≤ n ≤ 200000; 0 ≤ m ≤ 300000; 1 ≤ u,v ≤ n.',
    'Θ(n+m) времени, O(n+m) памяти.',
    ['Для зависимостей нужен топологический порядок.', 'Удаляйте вершины нулевой входной степени алгоритмом Кана и обновляйте длины путей.', 'Для ребра u→v обновите d[v]=max(d[v],d[u]+1). Если удалены не все n вершин, есть цикл, даже в другой компоненте.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m;cin>>n>>m;vector<vector<int>>g(n);vector<int>deg(n),d(n);while(m--){int u,v;cin>>u>>v;g[--u].push_back(--v);deg[v]++;}queue<int>q;for(int i=0;i<n;i++)if(!deg[i])q.push(i);int seen=0,ans=0;while(!q.empty()){int u=q.front();q.pop();seen++;ans=max(ans,d[u]);for(int v:g[u]){d[v]=max(d[v],d[u]+1);if(--deg[v]==0)q.push(v);}}cout<<(seen==n?ans:-1)<<"\\n";}',
    'К моменту удаления вершины все её предшественники обработаны, поэтому максимум длин определён окончательно. В непустом остатке без вершины нулевой степени последовательность предшественников обязательно замкнётся в цикл.',
    ('seen==n?ans:-1','true?ans:-1'),
    'int main(){int n,m;cin>>n>>m;vector<vector<int>>g(n);vector<int>deg(n),d(n);vector<bool>done(n);while(m--){int u,v;cin>>u>>v;g[--u].push_back(--v);deg[v]++;}int ans=0;for(int step=0;step<n;step++){int u=-1;for(int i=0;i<n;i++)if(!done[i]&&deg[i]==0){u=i;break;}if(u<0){cout<<-1<<"\\n";return 0;}done[u]=true;ans=max(ans,d[u]);for(int v:g[u]){deg[v]--;d[v]=max(d[v],d[u]+1);}}cout<<ans<<"\\n";}')

add('scc',11,'24. Зоны взаимной доступности',
    'Найдите число компонент сильной связности ориентированного графа. Две вершины принадлежат одной компоненте тогда и только тогда, когда каждая достижима из другой.',
    'n m; затем m ориентированных рёбер u v. Петли и повторения допустимы.',
    '1 ≤ n ≤ 200000; 0 ≤ m ≤ 300000; 1 ≤ u,v ≤ n.',
    'Θ(n+m) времени, O(n+m) памяти. Оба обхода итеративные.',
    ['Обычная связность после удаления направлений не подходит.', 'Получите порядок выхода DFS исходного графа и разверните все рёбра.', 'В обратном порядке выхода запускайте обходы транспонированного графа. Каждый новый обход выделяет одну КСС. Для длинной цепи используйте явный стек.'],
    '''int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m;cin>>n>>m;vector<vector<int>>g(n),r(n);while(m--){int u,v;cin>>u>>v;--u;--v;g[u].push_back(v);r[v].push_back(u);}vector<int>used(n),order;
for(int s=0;s<n;s++)if(!used[s]){vector<pair<int,int>>st{{s,0}};used[s]=1;while(!st.empty()){int u=st.back().first;int &i=st.back().second;if(i==(int)g[u].size()){order.push_back(u);st.pop_back();}else{int v=g[u][i++];if(!used[v]){used[v]=1;st.push_back({v,0});}}}}
fill(used.begin(),used.end(),0);reverse(order.begin(),order.end());int ans=0;for(int s:order)if(!used[s]){ans++;vector<int>st{s};used[s]=1;while(!st.empty()){int u=st.back();st.pop_back();for(int v:r[u])if(!used[v]){used[v]=1;st.push_back(v);}}}cout<<ans<<"\\n";}''',
    'Конденсация КСС ациклична. Компонента с наибольшим временем выхода не имеет исходящего ребра в ещё не обработанную компоненту в транспонированном графе; обход не покинет её, но достигнет всех её вершин.',
    ('for(int v:r[u])','for(int v:g[u])'),
    'int main(){int n,m;cin>>n>>m;vector<vector<int>>g(n);while(m--){int u,v;cin>>u>>v;g[--u].push_back(--v);}vector<vector<bool>>r(n,vector<bool>(n));for(int s=0;s<n;s++){vector<int>q{s};r[s][s]=true;for(size_t i=0;i<q.size();i++)for(int v:g[q[i]])if(!r[s][v]){r[s][v]=true;q.push_back(v);}}int z=0;for(int i=0;i<n;i++){bool first=true;for(int j=0;j<i;j++)if(r[i][j]&&r[j][i])first=false;z+=first;}cout<<z<<"\\n";}')

add('dijkstra',12,'25. Доставка с тарифами',
    'Найдите кратчайшие расстояния от s до всех вершин ориентированного графа с неотрицательными весами. Для недостижимых выведите −1. Ответы для вершин 1…n, по одному в строке.',
    'n m s; затем m строк u v w. Рёбра направлены u→v, петли и кратные рёбра возможны.',
    '1 ≤ n ≤ 200000; 0 ≤ m ≤ 300000; 0 ≤ w ≤ 10^9; вершины от 1 до n.',
    'O((n+m) log(n+m)) времени, O(n+m) памяти с ленивой очередью.',
    ['Очередь BFS не учитывает разные веса; нужен минимум текущего расстояния.', 'В min-heap храните пары расстояние, вершина. Улучшения добавляйте новой записью.', 'Если извлечённое расстояние уже не совпадает с d[u], пропустите его. Для каждой дуги релаксируйте d[v] через d[u]+w.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m,s;cin>>n>>m>>s;vector<vector<pair<int,ll>>>g(n+1);while(m--){int u,v;ll w;cin>>u>>v>>w;g[u].push_back({v,w});}const ll INF=4000000000000000000LL;vector<ll>d(n+1,INF);priority_queue<pair<ll,int>,vector<pair<ll,int>>,greater<pair<ll,int>>>q;d[s]=0;q.push({0,s});while(!q.empty()){auto[du,u]=q.top();q.pop();if(du!=d[u])continue;for(auto[v,w]:g[u])if(du+w<d[v]){d[v]=du+w;q.push({d[v],v});}}for(int i=1;i<=n;i++)cout<<(d[i]==INF?-1:d[i])<<"\\n";}',
    'Для извлечённой вершины с минимальной меткой любой ещё неизвестный путь должен пройти через вершину с не меньшей меткой и неотрицательное ребро. Он не может улучшить расстояние.',
    ('g[u].push_back({v,w});','g[u].push_back({v,w});g[v].push_back({u,w});'),
    'int main(){int n,m,s;cin>>n>>m>>s;vector<tuple<int,int,ll>>e(m);for(auto&[u,v,w]:e)cin>>u>>v>>w;const ll I=4000000000000000000LL;vector<ll>d(n+1,I);d[s]=0;for(int i=1;i<n;i++)for(auto[u,v,w]:e)if(d[u]!=I)d[v]=min(d[v],d[u]+w);for(int i=1;i<=n;i++)cout<<(d[i]==I?-1:d[i])<<"\\n";}')

add('floyd',12,'26. Таблица маршрутов',
    'Найдите расстояния для заданных пар вершин ориентированного графа. Веса могут быть отрицательными; отрицательных циклов во входе нет. Для недостижимой пары выведите INF, иначе целое расстояние.',
    'n m q; затем m строк u v w; затем q строк s t. Петли и кратные рёбра допустимы.',
    '1 ≤ n ≤ 400; 0 ≤ m ≤ 160000; 1 ≤ q ≤ 200000; |w| ≤ 10^9; вершины от 1 до n.',
    'O(n³+m+q) времени, O(n²) памяти.',
    ['Много запросов на небольшом графе оправдывают таблицу всех расстояний.', 'Пусть k ограничивает множество разрешённых промежуточных вершин.', 'Цикл по k должен быть внешним: d[i][j]=min(d[i][j],d[i][k]+d[k][j]). Не складывайте INF, диагональ инициализируйте нулём, кратные рёбра — минимумом.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m,q;cin>>n>>m>>q;const ll I=4000000000000000000LL;vector<vector<ll>>d(n,vector<ll>(n,I));for(int i=0;i<n;i++)d[i][i]=0;while(m--){int u,v;ll w;cin>>u>>v>>w;--u;--v;d[u][v]=min(d[u][v],w);}for(int k=0;k<n;k++)for(int i=0;i<n;i++)if(d[i][k]!=I)for(int j=0;j<n;j++)if(d[k][j]!=I)d[i][j]=min(d[i][j],d[i][k]+d[k][j]);while(q--){int s,t;cin>>s>>t;ll z=d[s-1][t-1];if(z==I)cout<<"INF\\n";else cout<<z<<"\\n";}}',
    'Оптимальный путь с промежуточными вершинами из 1…k либо не проходит k, либо разбивается в k на два пути с внутренними вершинами из 1…k−1. Отсутствие отрицательных циклов позволяет выбрать путь без повторений.',
    ('d[u][v]=min(d[u][v],w)','d[u][v]=w'),
    'int main(){int n,m,q;cin>>n>>m>>q;vector<tuple<int,int,ll>>e(m);for(auto&[u,v,w]:e)cin>>u>>v>>w;const ll I=4000000000000000000LL;while(q--){int s,t;cin>>s>>t;vector<ll>d(n+1,I);d[s]=0;for(int i=1;i<n;i++)for(auto[u,v,w]:e)if(d[u]!=I)d[v]=min(d[v],d[u]+w);if(d[t]==I)cout<<"INF\\n";else cout<<d[t]<<"\\n";}}',time=2000)

DSU='''struct DSU{vector<int>p,sz;DSU(int n):p(n),sz(n,1){iota(p.begin(),p.end(),0);}int find(int x){while(p[x]!=x){p[x]=p[p[x]];x=p[x];}return x;}bool join(int a,int b){a=find(a);b=find(b);if(a==b)return false;if(sz[a]<sz[b])swap(a,b);p[b]=a;sz[a]+=sz[b];return true;}};\n'''
add('connectivity',13,'27. Растущая сеть',
    'Изначально n вершин изолированы. Операция + u v добавляет неориентированное ребро. Операция ? u v спрашивает, соединены ли вершины путём. Для каждого запроса выведите YES или NO.',
    'n q; затем q операций. Повторные рёбра и петли допустимы.',
    '1 ≤ n,q ≤ 200000; вершины от 1 до n; хотя бы один запрос ?.',
    'O(n+q·α(n)) времени амортизированно, O(n) памяти.',
    ['Важно только, в какой компоненте находятся вершины; сами пути хранить не требуется.', 'DSU объединяет компоненты и находит их представителей.', 'Используйте сжатие путей и объединение по размеру. В запросе сравнивайте find(u), find(v), а не непосредственных родителей.'],
    DSU+'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,q;cin>>n>>q;DSU d(n+1);while(q--){char c;int u,v;cin>>c>>u>>v;if(c==\'+\')d.join(u,v);else cout<<(d.find(u)==d.find(v)?"YES":"NO")<<"\\n";}}',
    'Инвариант DSU: множества совпадают с компонентами добавленных рёбер. Новое ребро либо лежит внутри множества, либо соединяет ровно два множества.',
    ('d.find(u)==d.find(v)','d.p[u]==d.p[v]'),
    'int main(){int n,q;cin>>n>>q;vector<vector<int>>g(n+1);while(q--){char c;int u,v;cin>>c>>u>>v;if(c==\'+\'){g[u].push_back(v);g[v].push_back(u);}else{vector<bool>seen(n+1);vector<int>s{u};seen[u]=true;for(size_t i=0;i<s.size();i++)for(int w:g[s[i]])if(!seen[w]){seen[w]=true;s.push_back(w);}cout<<(seen[v]?"YES":"NO")<<"\\n";}}}')

add('mst',13,'28. Цена общей сети',
    'В неориентированном взвешенном графе найдите вес минимального остовного дерева. Если связать все вершины невозможно, выведите DISCONNECTED. Для одной вершины стоимость 0.',
    'n m; затем m строк u v w. Веса могут быть отрицательными, петли и кратные рёбра разрешены.',
    '1 ≤ n ≤ 200000; 0 ≤ m ≤ 300000; |w| ≤ 10^9; вершины от 1 до n.',
    'O(m log m + n) времени, O(n+m) памяти.',
    ['Обрабатывайте рёбра в порядке возрастания веса.', 'Добавляйте ребро, только если оно соединяет разные компоненты текущего леса.', 'Используйте DSU; накопите вес в long long. Для остова из n вершин должны быть выбраны ровно n−1 ребро.'],
    DSU+'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m;cin>>n>>m;vector<tuple<ll,int,int>>e(m);for(auto&[w,u,v]:e)cin>>u>>v>>w;sort(e.begin(),e.end());DSU d(n+1);ll ans=0;int cnt=0;for(auto[w,u,v]:e)if(d.join(u,v)){ans+=w;cnt++;}if(cnt!=n-1)cout<<"DISCONNECTED\\n";else cout<<ans<<"\\n";}',
    'Минимальное ребро, соединяющее текущие компоненты, безопасно по свойству разреза: в любом остове его можно обменять с не более лёгким ребром, пересекающим тот же разрез.',
    ('if(cnt!=n-1)','if(false)'),
    'int main(){int n,m;cin>>n>>m;vector<vector<pair<int,ll>>>g(n);while(m--){int u,v;ll w;cin>>u>>v>>w;--u;--v;g[u].push_back({v,w});g[v].push_back({u,w});}vector<ll>d(n,LLONG_MAX);vector<bool>used(n);d[0]=0;ll ans=0;for(int i=0;i<n;i++){int u=-1;for(int j=0;j<n;j++)if(!used[j]&&(u<0||d[j]<d[u]))u=j;if(d[u]==LLONG_MAX){cout<<"DISCONNECTED\\n";return 0;}used[u]=true;ans+=d[u];for(auto[v,w]:g[u])if(!used[v])d[v]=min(d[v],w);}cout<<ans<<"\\n";}')

add('kmp',14,'29. Все совпадения',
    'Найдите количество вхождений образца p в текст t. Перекрывающиеся вхождения учитываются. Строки непустые, содержат строчные латинские буквы.',
    'Первая строка — p, вторая — t.', '1 ≤ |p|,|t| ≤ 500000.',
    'Θ(|p|+|t|) времени, O(|p|) дополнительной памяти.',
    ['После несовпадения часть проверенного образца уже известна.', 'Префикс-функция образца позволяет перейти к следующему возможному совпадающему суффиксу.', 'Поддерживайте j совпавших символов. После полного совпадения увеличьте ответ и сделайте j=pi[j−1], сохранив перекрытия.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);string p,t;cin>>p>>t;vector<int>pi(p.size());for(int i=1;i<(int)p.size();i++){int j=pi[i-1];while(j&&p[i]!=p[j])j=pi[j-1];if(p[i]==p[j])j++;pi[i]=j;}int j=0,ans=0;for(char c:t){while(j&&p[j]!=c)j=pi[j-1];if(p[j]==c)j++;if(j==(int)p.size()){ans++;j=pi[j-1];}}cout<<ans<<"\\n";}',
    'j — длина максимального префикса образца, совпадающего с суффиксом уже прочитанного текста. Цепочка префикс-функции перечисляет все меньшие допустимые длины. Суммарно j увеличивается линейное число раз.',
    ('ans++;j=pi[j-1];','ans++;j=0;'),
    'int main(){string p,t;cin>>p>>t;int z=0;for(int i=0;i+(int)p.size()<=(int)t.size();i++){bool ok=true;for(int j=0;j<(int)p.size();j++)if(p[j]!=t[i+j]){ok=false;break;}z+=ok;}cout<<z<<"\\n";}')

add('period',14,'30. Сжатие повторением',
    'Найдите длину кратчайшего непустого блока, повторением которого целое число раз можно получить всю строку s. Один повтор допустим.',
    'Одна непустая строка из строчных латинских букв.', '1 ≤ |s| ≤ 500000.',
    'Θ(n) времени, O(n) памяти.',
    ['Совпадающие префикс и суффикс описывают возможный сдвиг повторения.', 'Вычислите префикс-функцию: кандидат p=n−pi[n−1].', 'Для целого числа повторов дополнительно нужно n%p==0. Иначе ответ n.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);string s;cin>>s;int n=s.size();vector<int>p(n);for(int i=1;i<n;i++){int j=p[i-1];while(j&&s[i]!=s[j])j=p[j-1];if(s[i]==s[j])j++;p[i]=j;}int k=n-p.back();cout<<(n%k==0?k:n)<<"\\n";}',
    'n−pi[n−1] — минимальный период в смысле совпадения символов при сдвиге. Чтобы строка была конкатенацией полных блоков, длина должна делиться на этот период.',
    ('n%k==0?k:n','k'),
    'int main(){string s;cin>>s;int n=s.size();for(int k=1;k<=n;k++){bool ok=true;for(int i=k;i<n;i++)if(s[i]!=s[i%k])ok=false;if(ok&&n%k==0){cout<<k<<"\\n";return 0;}}}')

add('weighted-intervals',15,'31. Проекты с прибылью',
    'У проекта есть время начала l, окончания r и прибыль v. Выберите непересекающиеся проекты с максимальной суммарной прибылью. Интервалы полуоткрытые [l,r), проекты с общей границей совместимы. Можно не выбирать ничего.',
    'n; затем n строк l r v.', '1 ≤ n ≤ 200000; 0 ≤ l < r ≤ 10^9; 0 ≤ v ≤ 10^9.',
    'O(n log n) времени, O(n) памяти.',
    ['Жадность по времени окончания максимизирует число встреч, но не прибыль.', 'Отсортируйте проекты по окончанию. dp[i] — лучший ответ на первых i проектах.', 'Либо пропустите проект i, либо добавьте его прибыль к dp[j], где j — число предыдущих проектов с окончанием ≤l[i]. j ищется upper_bound.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n;cin>>n;vector<tuple<ll,ll,ll>>a(n);for(auto&[r,l,v]:a)cin>>l>>r>>v;sort(a.begin(),a.end());vector<ll>ends(n),d(n+1);for(int i=0;i<n;i++)ends[i]=get<0>(a[i]);for(int i=0;i<n;i++){auto[r,l,v]=a[i];int j=upper_bound(ends.begin(),ends.begin()+i,l)-ends.begin();d[i+1]=max(d[i],d[j]+v);}cout<<d[n]<<"\\n";}',
    'В оптимальном наборе среди первых i проектов последний проект либо отсутствует, либо все другие выбранные заканчиваются не позже его начала. Два случая исчерпывают решения.',
    ('upper_bound(ends.begin(),ends.begin()+i,l)','lower_bound(ends.begin(),ends.begin()+i,l)'),
    'int main(){int n;cin>>n;vector<tuple<ll,ll,ll>>a(n);for(auto&[r,l,v]:a)cin>>l>>r>>v;sort(a.begin(),a.end());vector<ll>d(n+1);for(int i=0;i<n;i++){auto[r,l,v]=a[i];int j=0;for(int t=0;t<i;t++)if(get<0>(a[t])<=l)j=t+1;d[i+1]=max(d[i],d[j]+v);}cout<<d[n]<<"\\n";}')

add('jump-score',15,'32. Маршрут по платформам',
    'Стоя на платформе 1, нужно дойти до платформы n, каждый раз прыгая вперёд на 1…k позиций. При посещении i получаете a[i], включая первую и последнюю. Найдите максимальную сумму; пропустить достижение n нельзя.',
    'n k; затем n чисел a[i].', '1 ≤ k ≤ n ≤ 200000; −10^9 ≤ a[i] ≤ 10^9.',
    'Θ(n) времени, O(k) памяти при потоковом чтении.',
    ['Лучший путь к i заканчивается прыжком из одной из k предыдущих позиций.', 'dp[i]=a[i]+max(dp[j]) по i−k≤j<i. Это максимум в скользящем окне.', 'Храните кандидатов в монотонном деке. Инициализируйте только dp[1]=a[1]; нулевой фиктивный старт испортит отрицательные случаи.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,k;cin>>n>>k;deque<pair<int,ll>>d;ll ans=0;for(int i=0;i<n;i++){ll x;cin>>x;while(!d.empty()&&d.front().first<i-k)d.pop_front();ans=x+(i==0?0:d.front().second);while(!d.empty()&&d.back().second<=ans)d.pop_back();d.push_back({i,ans});}cout<<ans<<"\\n";}',
    'ДП перебирает все допустимые последние прыжки. Монотонный дек удаляет только кандидатов, которые хуже более нового значения и истекают раньше него.',
    ('ans=x+(i==0?0:d.front().second)','ans=x+(i==0?0:max(0LL,d.front().second))'),
    'int main(){int n,k;cin>>n>>k;vector<ll>a(n),d(n,LLONG_MIN);for(auto&x:a)cin>>x;d[0]=a[0];for(int i=1;i<n;i++)for(int j=max(0,i-k);j<i;j++)d[i]=max(d[i],d[j]+a[i]);cout<<d.back()<<"\\n";}')
BIT='''struct BIT{int n;vector<ll>t;BIT(int n):n(n),t(n+1){}void add(int i,ll x){for(;i<=n;i+=i&-i)t[i]+=x;}ll sum(int i){ll s=0;for(;i>0;i-=i&-i)s+=t[i];return s;}};\n'''
add('fenwick',16,'33. Живые измерения',
    'Поддерживайте массив. Операция + i x прибавляет x к a[i], операция ? l r требует сумму включённого отрезка. Каждый ответ выведите отдельно.',
    'n q; n исходных чисел; q операций одного из двух форматов.',
    '1 ≤ n,q ≤ 200000; |a[i]|,|x| ≤ 10^9; 1 ≤ i,l ≤ r ≤ n для соответствующих операций; хотя бы один запрос ?.',
    'O((n+q) log n) времени, O(n) памяти; возможна линейная первоначальная сборка.',
    ['Префиксные суммы устаревают после каждого изменения.', 'Дерево Фенвика хранит суммы блоков, определяемых младшим установленным битом индекса.', 'При изменении двигайтесь i+=i&−i; при сумме префикса i−=i&−i. Ответ [l,r] — prefix(r)−prefix(l−1).'],
    BIT+'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,q;cin>>n>>q;BIT b(n);for(int i=1;i<=n;i++){ll x;cin>>x;b.add(i,x);}while(q--){char c;int l;ll r;cin>>c>>l>>r;if(c==\'+\')b.add(l,r);else cout<<b.sum((int)r)-b.sum(l-1)<<"\\n";}}',
    'Каждая ячейка дерева содержит сумму блока длины lowbit(i). Префикс разбивается на непересекающиеся такие блоки; изменение посещает ровно блоки, содержащие позицию.',
    ('b.sum(l-1)','b.sum(l)'),
    'int main(){int n,q;cin>>n>>q;vector<ll>a(n+1);for(int i=1;i<=n;i++)cin>>a[i];while(q--){char c;int l;ll r;cin>>c>>l>>r;if(c==\'+\')a[l]+=r;else{ll z=0;for(int i=l;i<=r;i++)z+=a[i];cout<<z<<"\\n";}}}')

add('distinct-range',16,'34. Разнообразие на отрезке',
    'В неизменяемом массиве для каждого запроса l r найдите число различных значений на отрезке включительно. Выводите ответы в исходном порядке запросов.',
    'n q; n чисел массива; q строк l r.',
    '1 ≤ n,q ≤ 200000; |a[i]| ≤ 10^9; 1 ≤ l ≤ r ≤ n.',
    'O((n+q) log n) времени, O(n+q) памяти.',
    ['Все запросы известны заранее: их можно временно переставить.', 'Обрабатывайте запросы по возрастанию r. Для каждого значения оставляйте единицу только в его последнем вхождении.', 'Перед установкой единицы в r удалите предыдущую единицу того же значения. Сумма Фенвика на [l,r] даст число различных; сохраняйте ID запроса.'],
    BIT+'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,q;cin>>n>>q;vector<ll>a(n+1),ans(q);for(int i=1;i<=n;i++)cin>>a[i];vector<tuple<int,int,int>>qs(q);for(int i=0;i<q;i++){int l,r;cin>>l>>r;qs[i]={r,l,i};}sort(qs.begin(),qs.end());BIT b(n);map<ll,int>last;int cur=0;for(auto[r,l,id]:qs){while(cur<r){++cur;int p=last[a[cur]];if(p)b.add(p,-1);b.add(cur,1);last[a[cur]]=cur;}ans[id]=b.sum(r)-b.sum(l-1);}for(ll x:ans)cout<<x<<"\\n";}',
    'Значение встречается в [l,r] тогда и только тогда, когда его последнее вхождение среди первых r позиций не левее l. Поэтому каждой различной величине соответствует ровно одна единица в запросе.',
    ('if(p)b.add(p,-1);',''),
    'int main(){int n,q;cin>>n>>q;vector<ll>a(n);for(auto&x:a)cin>>x;while(q--){int l,r;cin>>l>>r;set<ll>s;for(int i=l-1;i<r;i++)s.insert(a[i]);cout<<s.size()<<"\\n";}}')

add('max-subarray',17,'35. Лучший участок после правки',
    'После каждого присваивания a[p]=x найдите максимальную сумму непрерывного участка всего массива. Пустой участок разрешён и имеет сумму 0. Ответ после каждой правки — с новой строки.',
    'n q; n исходных чисел; затем q строк p x.',
    '1 ≤ n,q ≤ 200000; |a[i]|,|x| ≤ 10^9; 1 ≤ p ≤ n.',
    'O(n+q log n) времени, O(n) памяти.',
    ['Для склейки двух половин одной максимальной суммы недостаточно.', 'Храните сумму целиком, лучший префикс, лучший суффикс и лучший участок.', 'best=max(left.best,right.best,left.suffix+right.prefix). Префикс и суффикс тоже могут захватывать целую соседнюю половину. В листе максимум равен max(0,x).'],
    '''struct N{ll s=0,p=0,q=0,b=0;};N join(N a,N b){return {a.s+b.s,max(a.p,a.s+b.p),max(b.q,b.s+a.q),max({a.b,b.b,a.q+b.p})};}N leaf(ll x){return {x,max(0LL,x),max(0LL,x),max(0LL,x)};}
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,q;cin>>n>>q;int z=1;while(z<n)z*=2;vector<N>t(2*z);for(int i=0;i<n;i++){ll x;cin>>x;t[z+i]=leaf(x);}for(int i=z-1;i;i--)t[i]=join(t[2*i],t[2*i+1]);while(q--){int p;ll x;cin>>p>>x;p=z+p-1;t[p]=leaf(x);for(p/=2;p;p/=2)t[p]=join(t[2*p],t[2*p+1]);cout<<t[1].b<<"\\n";}}''',
    'Лучший участок либо целиком слева, либо целиком справа, либо пересекает границу и состоит из суффикса слева и префикса справа. Это исчерпывающая классификация; инвариант узлов сохраняется после обновления.',
    ('a.q+b.p','a.p+b.q'),
    'int main(){int n,q;cin>>n>>q;vector<ll>a(n);for(auto&x:a)cin>>x;while(q--){int p;ll x;cin>>p>>x;a[p-1]=x;ll z=0,s=0;for(ll v:a){s=max(0LL,s+v);z=max(z,s);}cout<<z<<"\\n";}}')

add('lazy-max',17,'36. Массовая коррекция',
    'Операция + l r x прибавляет x всем значениям на [l,r]. Операция ? l r запрашивает максимум на [l,r]. Все отрезки включают обе границы.',
    'n q; затем n исходных значений; затем q операций указанных форматов.',
    '1 ≤ n,q ≤ 200000; |a[i]|,|x| ≤ 10^9; 1 ≤ l ≤ r ≤ n; хотя бы один запрос ?.',
    'O(n+q log n) времени, O(n) памяти.',
    ['Одинаковое прибавление к целому сегменту меняет его максимум на ту же величину.', 'Храните максимум и отложенное прибавление. Перед частичным спуском проталкивайте метку детям.', 'Для полного покрытия достаточно изменить два числа в узле. Нейтральное значение для непересечения — минус бесконечность, а не 0.'],
    '''vector<ll>t,lazy,a;void build(int v,int l,int r){if(l==r){t[v]=a[l];return;}int m=(l+r)/2;build(v*2,l,m);build(v*2+1,m+1,r);t[v]=max(t[v*2],t[v*2+1]);}void apply(int v,ll x){t[v]+=x;lazy[v]+=x;}void push(int v){apply(v*2,lazy[v]);apply(v*2+1,lazy[v]);lazy[v]=0;}
void upd(int v,int l,int r,int L,int R,ll x){if(R<l||r<L)return;if(L<=l&&r<=R){apply(v,x);return;}push(v);int m=(l+r)/2;upd(v*2,l,m,L,R,x);upd(v*2+1,m+1,r,L,R,x);t[v]=max(t[v*2],t[v*2+1]);}
ll ask(int v,int l,int r,int L,int R){if(R<l||r<L)return LLONG_MIN;if(L<=l&&r<=R)return t[v];push(v);int m=(l+r)/2;return max(ask(v*2,l,m,L,R),ask(v*2+1,m+1,r,L,R));}
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,q;cin>>n>>q;a.resize(n);t.resize(4*n);lazy.resize(4*n);for(auto&x:a)cin>>x;build(1,0,n-1);while(q--){char c;int l,r;cin>>c>>l>>r;--l;--r;if(c=='+'){ll x;cin>>x;upd(1,0,n-1,l,r,x);}else cout<<ask(1,0,n-1,l,r)<<"\\n";}}''',
    'Максимум после равномерной прибавки x равен старому максимуму плюс x. Отложенная метка хранит изменения, уже учтённые в родителе, но ещё не переданные детям. push восстанавливает согласованность перед чтением дочерних узлов.',
    ('if(R<l||r<L)return LLONG_MIN','if(R<l||r<L)return 0'),
    'int main(){int n,q;cin>>n>>q;vector<ll>a(n);for(auto&x:a)cin>>x;while(q--){char c;int l,r;cin>>c>>l>>r;--l;if(c==\'+\'){ll x;cin>>x;for(int i=l;i<r;i++)a[i]+=x;}else{ll z=LLONG_MIN;for(int i=l;i<r;i++)z=max(z,a[i]);cout<<z<<"\\n";}}}')

TREAP='''mt19937 rng(712367821);struct N{ll x,s;unsigned pr;int sz=1,cnt=1;bool rev=false;N *l=nullptr,*r=nullptr;N(ll x):x(x),s(x),pr(rng()){}};int size(N*t){return t?t->sz:0;}ll sum(N*t){return t?t->s:0;}void pull(N*t){if(t){t->sz=size(t->l)+size(t->r)+t->cnt;t->s=sum(t->l)+sum(t->r)+t->x*t->cnt;}}void push(N*t){if(t&&t->rev){swap(t->l,t->r);if(t->l)t->l->rev^=1;if(t->r)t->r->rev^=1;t->rev=false;}}N*merge(N*a,N*b){if(!a)return b;if(!b)return a;push(a);push(b);if(a->pr>b->pr){a->r=merge(a->r,b);pull(a);return a;}b->l=merge(a,b->l);pull(b);return b;}\n'''
add('treap-order',18,'37. Рейтинг с повторами',
    'Поддерживайте мультимножество. + x добавляет одно вхождение; - x удаляет одно вхождение, если оно есть; ? k возвращает k-й по возрастанию элемент с учётом повторений. Для недопустимого k выведите NONE.',
    'q; затем q операций. Изначально мультимножество пусто.',
    '1 ≤ q ≤ 200000; |x| ≤ 10^9; 1 ≤ k ≤ 200000; хотя бы один запрос ?.',
    'Ожидаемое O(q log q) времени, O(q) памяти для декартова дерева; не гарантия худшего случая.',
    ['В каждом узле дерева поиска храните число повторений ключа и размер всего поддерева.', 'При случайных независимых приоритетах дерево ожидаемо сбалансировано. Поддерживайте размеры после изменений.', 'Для k-го элемента сравните k с размером левого поддерева и блоком cnt текущего ключа; иначе переходите вправо, вычитая оба размера.'],
    TREAP+'''void split(N*t,ll x,N*&a,N*&b){if(!t){a=b=nullptr;return;}if(t->x<x){a=t;split(t->r,x,a->r,b);pull(a);}else{b=t;split(t->l,x,a,b->l);pull(b);}}ll kth(N*t,int k){while(t){int z=size(t->l);if(k<=z)t=t->l;else if(k<=z+t->cnt)return t->x;else{k-=z+t->cnt;t=t->r;}}return 0;}
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int q;cin>>q;N*root=nullptr;while(q--){char op;ll x;cin>>op>>x;if(op=='?'){if(x<1||x>size(root))cout<<"NONE\\n";else cout<<kth(root,x)<<"\\n";}else{N*a,*b,*c;split(root,x,a,b);split(b,x+1,b,c);if(op=='+'){if(b)b->cnt++;else b=new N(x);}else if(b){if(--b->cnt==0){delete b;b=nullptr;}}pull(b);root=merge(merge(a,b),c);}}}''',
    'split выделяет ключи меньше x, равные x и больше x. Куча приоритетов и порядок ключей сохраняются merge. Поддерево содержит size(left)+cnt+size(right) элементов, что оправдывает выбор ветви при поиске ранга.',
    ('if(b)b->cnt++;','if(b)b->cnt=1;'),
    'int main(){int q;cin>>q;multiset<ll>s;while(q--){char c;ll x;cin>>c>>x;if(c==\'+\')s.insert(x);else if(c==\'-\'){auto it=s.find(x);if(it!=s.end())s.erase(it);}else{if(x>(ll)s.size())cout<<"NONE\\n";else{auto it=s.begin();advance(it,x-1);cout<<*it<<"\\n";}}}}')

add('treap-sequence',18,'38. Монтаж последовательности',
    'Нужно выполнять R l r — разворот участка массива — и S l r — сумму его элементов. Индексы относятся к текущему порядку. Для каждого S выведите сумму.',
    'n q; n исходных чисел; q операций R или S.',
    '1 ≤ n,q ≤ 200000; |a[i]| ≤ 10^9; 1 ≤ l ≤ r ≤ n; хотя бы один запрос S.',
    'Ожидаемое O((n+q) log n) времени, O(n) памяти. Линейное построение также возможно.',
    ['Обычное дерево по значениям не сохраняет порядок элементов массива.', 'Используйте декартово дерево с неявным ключом — позицией, вычисляемой по размерам поддеревьев.', 'Разрежьте по r и l−1, выделив участок. Для R переключите ленивый флаг rev; для S прочитайте сумму. Перед спуском push, после изменения pull; затем склейте части.'],
    TREAP+'''void split(N*t,int k,N*&a,N*&b){if(!t){a=b=nullptr;return;}push(t);if(size(t->l)>=k){b=t;split(t->l,k,a,b->l);pull(b);}else{a=t;split(t->r,k-size(t->l)-1,a->r,b);pull(a);}}
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,q;cin>>n>>q;N*root=nullptr;for(int i=0;i<n;i++){ll x;cin>>x;root=merge(root,new N(x));}while(q--){char op;int l,r;cin>>op>>l>>r;N*a,*b,*c;split(root,r,a,c);split(a,l-1,a,b);if(op=='R')b->rev^=1;else cout<<sum(b)<<"\\n";root=merge(merge(a,b),c);}}''',
    'Размер левого поддерева задаёт ранг корня. Два split выделяют ровно нужные позиции. Разворот меняет порядок, но сохраняет сумму и размер; ленивый флаг композиционно складывается по XOR.',
    ('b->rev^=1','b->rev=false'),
    'int main(){int n,q;cin>>n>>q;vector<ll>a(n);for(auto&x:a)cin>>x;while(q--){char c;int l,r;cin>>c>>l>>r;--l;if(c==\'R\')reverse(a.begin()+l,a.begin()+r);else{ll s=0;for(int i=l;i<r;i++)s+=a[i];cout<<s<<"\\n";}}}')
LCA='''int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,q;cin>>n>>q;vector<vector<pair<int,ll>>>g(n);for(int i=1;i<n;i++){int u,v;ll w;cin>>u>>v>>w;--u;--v;g[u].push_back({v,w});g[v].push_back({u,w});}int L=1;while((1<<L)<=n)L++;vector<vector<int>>up(L,vector<int>(n));vector<vector<ll>>mx(L,vector<ll>(n,LLONG_MIN));vector<int>dep(n,-1),order{0};vector<ll>d(n);dep[0]=0;for(size_t i=0;i<order.size();i++){int u=order[i];for(auto[v,w]:g[u])if(dep[v]<0){dep[v]=dep[u]+1;up[0][v]=u;mx[0][v]=w;d[v]=d[u]+w;order.push_back(v);}}for(int j=1;j<L;j++)for(int v=0;v<n;v++){up[j][v]=up[j-1][up[j-1][v]];mx[j][v]=max(mx[j-1][v],mx[j-1][up[j-1][v]]);}while(q--){int u,v;cin>>u>>v;--u;--v;int a=u,b=v;ll best=LLONG_MIN;if(dep[u]<dep[v])swap(u,v);int delta=dep[u]-dep[v];for(int j=0;j<L;j++)if(delta>>j&1){best=max(best,mx[j][u]);u=up[j][u];}if(u!=v){for(int j=L-1;j>=0;j--)if(up[j][u]!=up[j][v]){best=max({best,mx[j][u],mx[j][v]});u=up[j][u];v=up[j][v];}best=max({best,mx[0][u],mx[0][v]});u=up[0][u];}RESULT}}\n'''
add('tree-distance',19,'39. Расстояния в дереве',
    'Дано неориентированное дерево с весами рёбер. Для каждого запроса u v найдите сумму весов единственного простого пути. Путь из вершины в себя имеет сумму 0.',
    'n q; n−1 строк u v w; q строк u v. Вход гарантированно является деревом.',
    '1 ≤ n,q ≤ 200000; |w| ≤ 10^9; вершины от 1 до n.',
    'O((n+q) log n) времени, O(n log n) памяти; бинарные подъёмы.',
    ['Путь проходит через наименьшего общего предка u и v.', 'Сохраните сумму весов от корня до каждой вершины и предков на расстояниях 1,2,4,…', 'Ответ d[u]+d[v]−2·d[LCA(u,v)]. Сначала уравняйте глубины, затем поднимайте обе вершины от больших степеней к малым.'],
    LCA.replace('RESULT','cout<<d[a]+d[b]-2*d[u]<<"\\n";'),
    'Пути от корня к u и v имеют общий префикс до LCA. Его вес посчитан дважды и должен быть вычтен дважды. Отрицательные веса не мешают, поскольку простой путь в дереве единственен.',
    ('d[a]+d[b]-2*d[u]','d[a]+d[b]-d[u]'),
    'int main(){int n,q;cin>>n>>q;vector<vector<pair<int,ll>>>g(n);for(int i=1;i<n;i++){int u,v;ll w;cin>>u>>v>>w;--u;--v;g[u].push_back({v,w});g[v].push_back({u,w});}while(q--){int s,t;cin>>s>>t;--s;--t;vector<int>p(n,-1),o{s};vector<ll>d(n);p[s]=s;for(size_t i=0;i<o.size();i++)for(auto[v,w]:g[o[i]])if(p[v]<0){p[v]=o[i];d[v]=d[o[i]]+w;o.push_back(v);}cout<<d[t]<<"\\n";}}')

add('tree-max',19,'40. Самый дорогой переход',
    'В неориентированном дереве для каждого запроса найдите максимальный вес ребра на единственном простом пути u→v. Если u=v, выведите 0. Веса могут быть отрицательными.',
    'n q; n−1 строк u v w; q строк u v. Гарантировано дерево.',
    '1 ≤ n,q ≤ 200000; |w| ≤ 10^9; вершины от 1 до n.',
    'O((n+q) log n) времени, O(n log n) памяти.',
    ['Максимум нельзя получить вычитанием двух префиксных максимумов.', 'В таблице подъёмов храните не только предка, но и максимум на каждом прыжке.', 'Во время уравнивания глубин и поиска LCA объединяйте максимумы пройденных блоков. Начните с −∞; случай u=v обработайте отдельно.'],
    LCA.replace('RESULT','cout<<(a==b?0:best)<<"\\n";'),
    'Подъёмы разбивают обе части пути до LCA на непересекающиеся блоки степенных длин. Максимум по объединению равен максимуму их максимумов; нейтральное значение −∞ сохраняет отрицательные ответы.',
    ('ll best=LLONG_MIN','ll best=0'),
    'int main(){int n,q;cin>>n>>q;vector<vector<pair<int,ll>>>g(n);for(int i=1;i<n;i++){int u,v;ll w;cin>>u>>v>>w;--u;--v;g[u].push_back({v,w});g[v].push_back({u,w});}while(q--){int s,t;cin>>s>>t;--s;--t;vector<int>p(n,-1),o{s};vector<ll>d(n,LLONG_MIN);p[s]=s;for(size_t i=0;i<o.size();i++)for(auto[v,w]:g[o[i]])if(p[v]<0){p[v]=o[i];d[v]=max(d[o[i]],w);o.push_back(v);}cout<<(s==t?0:d[t])<<"\\n";}}')

LOWLINK='''int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m;cin>>n>>m;vector<vector<pair<int,int>>>g(n);for(int i=0;i<m;i++){int u,v;cin>>u>>v;--u;--v;g[u].push_back({v,i});g[v].push_back({u,i});}vector<int>tin(n,-1),low(n),parent(n,-1),pe(n,-1),idx(n),children(n);vector<bool>cut(n);int timer=0,bridges=0;for(int root=0;root<n;root++)if(tin[root]<0){vector<int>st{root};tin[root]=low[root]=timer++;while(!st.empty()){int u=st.back();if(idx[u]<(int)g[u].size()){auto[v,id]=g[u][idx[u]++];if(id==pe[u])continue;if(tin[v]<0){parent[v]=u;pe[v]=id;children[u]++;tin[v]=low[v]=timer++;st.push_back(v);}else low[u]=min(low[u],tin[v]);}else{st.pop_back();int p=parent[u];if(p<0){cut[u]=children[u]>1;}else{low[p]=min(low[p],low[u]);if(low[u]>tin[p])bridges++;if(parent[p]>=0&&low[u]>=tin[p])cut[p]=true;}}}}RESULT}\n'''
add('bridges',20,'41. Хрупкие связи',
    'Найдите количество мостов: рёбер, удаление одного из которых увеличивает число компонент связности неориентированного графа. Кратные рёбра считаются отдельными рёбрами.',
    'n m; затем m строк u v. Граф может быть несвязным, с петлями и кратными рёбрами.',
    '1 ≤ n ≤ 200000; 0 ≤ m ≤ 300000; вершины от 1 до n.',
    'Θ(n+m) времени, O(n+m) памяти. Итеративный DFS избегает переполнения стека.',
    ['Для ребра DFS в ребёнка важно, может ли его поддерево вернуться выше родителя.', 'low[v] — минимальное время входа, достижимое из поддерева v по рёбрам дерева и одному обратному ребру.', 'Ребро parent→v — мост при low[v]>tin[parent]. Пропускайте только ID родительского ребра, а не все рёбра к родителю.'],
    LOWLINK.replace('RESULT','cout<<bridges<<"\\n";'),
    'Если low[v]≤tin[parent], существует обходной путь к родителю или его предку. Иначе поддерево связано с остальным графом только рассматриваемым ребром. Второе параллельное ребро является таким обходом.',
    ('if(id==pe[u])continue','if(v==parent[u])continue'),
    'int main(){int n,m;cin>>n>>m;vector<pair<int,int>>e(m);for(auto&[u,v]:e){cin>>u>>v;--u;--v;}auto count=[&](int skip){vector<vector<int>>g(n);for(int i=0;i<m;i++)if(i!=skip){auto[u,v]=e[i];g[u].push_back(v);g[v].push_back(u);}vector<bool>seen(n);int z=0;for(int s=0;s<n;s++)if(!seen[s]){z++;vector<int>q{s};seen[s]=true;for(size_t i=0;i<q.size();i++)for(int v:g[q[i]])if(!seen[v]){seen[v]=true;q.push_back(v);}}return z;};int base=count(-1),ans=0;for(int i=0;i<m;i++)ans+=count(i)>base;cout<<ans<<"\\n";}')

add('articulation',20,'42. Узлы отказа',
    'Найдите количество точек сочленения: вершин, после удаления которых вместе со всеми инцидентными рёбрами число компонент связности увеличивается. Удалённая вершина отдельной компонентой не считается.',
    'n m; затем m строк u v неориентированного графа; петли и кратные рёбра допустимы.',
    '1 ≤ n ≤ 200000; 0 ≤ m ≤ 300000; вершины от 1 до n.',
    'Θ(n+m) времени, O(n+m) памяти.',
    ['Условия для обычной вершины DFS и корня различаются.', 'Некорневая вершина u разделяет граф, если у неё есть ребёнок v с low[v]≥tin[u].', 'Корень — точка сочленения только при двух или более детях в дереве DFS. Проверяйте каждый компонент и считайте вершины, не подходящих детей.'],
    LOWLINK.replace('RESULT','cout<<count(cut.begin(),cut.end(),true)<<"\\n";'),
    'После удаления некорневой u поддерево v отделится от родительской части, если не имеет ребра к строгому предку u. У корня родительской части нет: разделение создают лишь два различных дочерних поддерева.',
    ('children[u]>1','children[u]>0'),
    'int main(){int n,m;cin>>n>>m;vector<vector<int>>g(n);while(m--){int u,v;cin>>u>>v;--u;--v;g[u].push_back(v);g[v].push_back(u);}auto count=[&](int skip){vector<bool>s(n);int z=0;for(int i=0;i<n;i++)if(i!=skip&&!s[i]){z++;vector<int>q{i};s[i]=true;for(size_t j=0;j<q.size();j++)for(int v:g[q[j]])if(v!=skip&&!s[v]){s[v]=true;q.push_back(v);}}return z;};int b=count(-1),z=0;for(int i=0;i<n;i++)z+=count(i)>b;cout<<z<<"\\n";}')

add('aho',21,'43. Поиск по словарю',
    'Для каждого образца посчитайте число его вхождений в общий текст. Перекрытия учитываются. Одинаковые образцы во входе требуют отдельных одинаковых ответов. Ответы в порядке образцов, по одному в строке.',
    'k; затем k непустых образцов; затем непустой текст. Все символы — a…z.',
    '1 ≤ k ≤ 200000; суммарная длина образцов ≤ 200000; длина текста ≤ 500000.',
    'O(26·P+T+k) времени и O(26·P+T+k) памяти с плотными переходами, P — суммарная длина образцов, T — длина текста.',
    ['Независимый поиск каждого образца повторно просматривает текст.', 'Постройте бор и суффиксные ссылки Ахо—Корасик, затем считайте посещения состояний на тексте.', 'Накопите счётчики в суффиксных ссылках в обратном порядке BFS. Ответ образца — счётчик его конечной вершины, включая совпадения по ссылкам.'],
    '''struct Node{array<int,26>go{};int link=0;ll hits=0;};int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int k;cin>>k;vector<Node>t(1);vector<int>end(k);for(int i=0;i<k;i++){string s;cin>>s;int u=0;for(char c:s){int x=c-'a';if(!t[u].go[x]){t[u].go[x]=t.size();t.emplace_back();}u=t[u].go[x];}end[i]=u;}queue<int>q;vector<int>order;for(int c=0;c<26;c++)if(t[0].go[c])q.push(t[0].go[c]);while(!q.empty()){int u=q.front();q.pop();order.push_back(u);for(int c=0;c<26;c++){int v=t[u].go[c];if(v){t[v].link=t[t[u].link].go[c];q.push(v);}else t[u].go[c]=t[t[u].link].go[c];}}string s;cin>>s;int u=0;for(char c:s){u=t[u].go[c-'a'];t[u].hits++;}reverse(order.begin(),order.end());for(int v:order)t[t[v].link].hits+=t[v].hits;for(int v:end)cout<<t[v].hits<<"\\n";}''',
    'Состояние после символа соответствует самому длинному суффиксу текста, который есть в боре. Все более короткие совпадающие образцы лежат на цепочке суффиксных ссылок. Обратный BFS передаёт каждый счётчик ровно к этим предкам.',
    ('t[t[v].link].hits+=t[v].hits','t[t[v].link].hits+=0'),
    'int main(){int k;cin>>k;vector<string>p(k);for(auto&s:p)cin>>s;string t;cin>>t;for(auto&s:p){ll z=0;for(int i=0;i+(int)s.size()<=(int)t.size();i++){bool ok=true;for(int j=0;j<(int)s.size();j++)if(s[j]!=t[i+j]){ok=false;break;}z+=ok;}cout<<z<<"\\n";}}')

add('sam',21,'44. Словарь подстрок',
    'Найдите количество различных непустых подстрок строки. Одинаковые подстроки, встречающиеся в разных местах, учитываются один раз.',
    'Непустая строка из a…z.', '1 ≤ n ≤ 200000.',
    'O(26n) времени и O(26n) памяти — линейно при фиксированном алфавите.',
    ['Перечисление всех подстрок требует квадратичного времени и ещё больше памяти при копировании.', 'Суффиксный автомат объединяет подстроки с одинаковыми множествами позиций окончания.', 'Каждое состояние v, кроме корня, представляет ровно len[v]−len[link[v]] различных длин. Постройте автомат с клонами и просуммируйте эти разности в long long.'],
    '''struct N{array<int,26>go;int len=0,link=-1;N(){go.fill(-1);}};int main(){ios::sync_with_stdio(false);cin.tie(nullptr);string s;cin>>s;vector<N>t(1);int last=0;for(char ch:s){int c=ch-'a',cur=t.size();t.emplace_back();t[cur].len=t[last].len+1;int p=last;while(p!=-1&&t[p].go[c]==-1){t[p].go[c]=cur;p=t[p].link;}if(p==-1)t[cur].link=0;else{int q=t[p].go[c];if(t[p].len+1==t[q].len)t[cur].link=q;else{int clone=t.size();t.push_back(t[q]);t[clone].len=t[p].len+1;while(p!=-1&&t[p].go[c]==q){t[p].go[c]=clone;p=t[p].link;}t[q].link=t[cur].link=clone;}}last=cur;}ll ans=0;for(int v=1;v<(int)t.size();v++)ans+=t[v].len-t[t[v].link].len;cout<<ans<<"\\n";}''',
    'Состояние представляет все длины от len(link(v))+1 до len(v), и для каждой длины — ровно одну строку. Клоны разделяют классы при нарушении этой границы, сохраняя язык подстрок.',
    ('ans+=t[v].len-t[t[v].link].len','ans+=t[v].len'),
    'int main(){string s;cin>>s;set<string>q;for(int i=0;i<(int)s.size();i++){string x;for(int j=i;j<(int)s.size();j++){x+=s[j];q.insert(x);}}cout<<q.size()<<"\\n";}')

add('matching',22,'45. Распределение наставников',
    'Дан двудольный граф: n студентов и m наставников. Каждое разрешённое ребро означает совместимую пару. Один участник может входить не более чем в одну выбранную пару. Выведите максимальное количество пар.',
    'n m e; затем e строк u v, где u — номер студента, v — номер наставника. Повторные рёбра допустимы.',
    '1 ≤ n,m ≤ 20000; 0 ≤ e ≤ 200000; 1 ≤ u ≤ n, 1 ≤ v ≤ m.',
    'O((e+n+m)√(n+m)) времени, O(e+n+m) памяти для Хопкрофта—Карпа.',
    ['Жадный выбор свободной пары может перекрыть единственный вариант другого студента.', 'Ищите увеличивающие пути: чередуйте невыбранные и выбранные рёбра.', 'Хопкрофт—Карп строит BFS-слои до ближайших свободных правых вершин и за фазу находит набор кратчайших увеличивающих путей. Считайте успешные увеличения.'],
    '''int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m,e;cin>>n>>m>>e;vector<vector<int>>g(n+1);while(e--){int u,v;cin>>u>>v;g[u].push_back(v);}vector<int>a(n+1),b(m+1),d(n+1),it(n+1);int ans=0,INF=n+m+1;
while(true){queue<int>q;fill(d.begin(),d.end(),INF);for(int u=1;u<=n;u++)if(!a[u]){d[u]=0;q.push(u);}int limit=INF;while(!q.empty()){int u=q.front();q.pop();if(d[u]>=limit)continue;for(int v:g[u]){if(!b[v])limit=d[u]+1;else if(d[b[v]]==INF){d[b[v]]=d[u]+1;q.push(b[v]);}}}if(limit==INF)break;fill(it.begin(),it.end(),0);function<bool(int)>dfs=[&](int u){for(int&i=it[u];i<(int)g[u].size();i++){int v=g[u][i];if((!b[v]&&d[u]+1==limit)||(b[v]&&d[b[v]]==d[u]+1&&dfs(b[v]))){a[u]=v;b[v]=u;return true;}}d[u]=INF;return false;};for(int u=1;u<=n;u++)if(!a[u]&&dfs(u))ans++;}cout<<ans<<"\\n";}''',
    'Переворот увеличивающего пути увеличивает паросочетание на один. Если увеличивающих путей нет, симметрическая разность с гипотетически большим паросочетанием дала бы такой путь — противоречие. BFS-фазы ограничивают число проходов.',
    ('(b[v]&&d[b[v]]==d[u]+1&&dfs(b[v]))','false'),
    'int n,m,best=0;vector<vector<int>>g;vector<bool>used;void f(int u,int z){if(u==n){best=max(best,z);return;}f(u+1,z);for(int v:g[u])if(!used[v]){used[v]=true;f(u+1,z+1);used[v]=false;}}int main(){int e;cin>>n>>m>>e;g.resize(n);used.resize(m);while(e--){int u,v;cin>>u>>v;g[u-1].push_back(v-1);}f(0,0);cout<<best<<"\\n";}',time=2000)

add('flow',22,'46. Пропускная способность',
    'Найдите максимальный поток из вершины 1 в вершину n в ориентированной сети. У каждой дуги задана неотрицательная целая пропускная способность. Параллельные и встречные дуги независимы.',
    'n m; затем m строк u v c. Петель нет.',
    '2 ≤ n ≤ 500; 0 ≤ m ≤ 10000; 1 ≤ u,v ≤ n, u≠v; 0 ≤ c ≤ 10^9.',
    'O(n²m) времени в общем случае для Диница, O(n+m) памяти. Это не утверждение об абсолютной оптимальности среди всех потоковых алгоритмов.',
    ['После отправки потока важно уметь отменять часть прежнего выбора.', 'Каждой дуге сопоставьте отдельную обратную дугу остаточной сети.', 'Диниц строит уровни BFS и отправляет блокирующий поток по рёбрам следующего уровня. Используйте указатели текущего ребра и long long для потока.'],
    '''struct E{int v,rev;ll cap;};int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m;cin>>n>>m;vector<vector<E>>g(n);while(m--){int u,v;ll c;cin>>u>>v>>c;--u;--v;int a=g[u].size(),b=g[v].size();g[u].push_back({v,b,c});g[v].push_back({u,a,0});}ll ans=0;vector<int>d(n),it(n);while(true){fill(d.begin(),d.end(),-1);queue<int>q;q.push(0);d[0]=0;while(!q.empty()){int u=q.front();q.pop();for(auto e:g[u])if(e.cap>0&&d[e.v]<0){d[e.v]=d[u]+1;q.push(e.v);}}if(d[n-1]<0)break;fill(it.begin(),it.end(),0);function<ll(int,ll)>dfs=[&](int u,ll f)->ll{if(u==n-1)return f;for(int&i=it[u];i<(int)g[u].size();i++){E&e=g[u][i];if(e.cap>0&&d[e.v]==d[u]+1){ll z=dfs(e.v,min(f,e.cap));if(z){e.cap-=z;g[e.v][e.rev].cap+=z;return z;}}}return 0;};while(ll z=dfs(0,LLONG_MAX))ans+=z;}cout<<ans<<"\\n";}''',
    'Каждое увеличение сохраняет ограничения ёмкостей и баланс внутренних вершин. Если пути в остаточной сети нет, множество достижимых из истока образует разрез с ёмкостью текущего потока — значит, больший поток невозможен.',
    ('ll ans=0;vector<int>d(n),it(n);','int ans=0;vector<int>d(n),it(n);'),
    'int main(){int n,m;cin>>n>>m;vector<tuple<int,int,ll>>e(m);for(auto&[u,v,c]:e){cin>>u>>v>>c;--u;--v;}vector<bool>s(n);s[0]=true;ll best=LLONG_MAX;function<void(int)>f=[&](int i){if(i==n-1){ll z=0;for(auto[u,v,c]:e)if(s[u]&&!s[v])z+=c;best=min(best,z);return;}s[i]=false;f(i+1);s[i]=true;f(i+1);};f(1);cout<<best<<"\\n";}',time=2000)

add('tsp',23,'47. Замкнутый маршрут',
    'Найдите минимальную стоимость маршрута, который начинается в городе 1, посещает каждый другой город ровно один раз и возвращается в 1. Матрица стоимости ориентированная и полная; для одного города ответ 0.',
    'n; затем n строк по n целых чисел c[i][j]. Диагональ нулевая.',
    '1 ≤ n ≤ 18; 0 ≤ c[i][j] ≤ 10^9.',
    'O(n²·2^n) времени, O(n·2^n) памяти — точное ДП по подмножествам.',
    ['Полный перебор порядков даёт факториал; многие префиксы отличаются только порядком уже посещённых городов.', 'dp[mask][v] — минимальная стоимость пути из 1 с множеством посещённых mask и концом v.', 'Начните с dp[1][0]=0. Добавляйте ещё не посещённый город. В конце обязательно прибавьте стоимость возвращения v→1.'],
    'int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n;cin>>n;vector<vector<ll>>c(n,vector<ll>(n));for(auto&r:c)for(auto&x:r)cin>>x;const ll I=4000000000000000000LL;int M=1<<n;vector<ll>d((size_t)M*n,I);d[n]=0;for(int mask=1;mask<M;mask+=2)for(int v=0;v<n;v++)if(d[(size_t)mask*n+v]!=I)for(int u=0;u<n;u++)if(!(mask>>u&1)){auto&z=d[(size_t)(mask|1<<u)*n+u];z=min(z,d[(size_t)mask*n+v]+c[v][u]);}ll ans=I;for(int v=0;v<n;v++)ans=min(ans,d[(size_t)(M-1)*n+v]+c[v][0]);cout<<ans<<"\\n";}',
    'Будущее пути зависит лишь от уже посещённых городов и последнего города, поэтому среди одинаковых состояний достаточно самого дешёвого префикса. Каждый переход добавляет один город и сохраняет простоту маршрута.',
    ('+c[v][0]','+0'),
    'int main(){int n;cin>>n;vector<vector<ll>>c(n,vector<ll>(n));for(auto&r:c)for(auto&x:r)cin>>x;vector<int>p;for(int i=1;i<n;i++)p.push_back(i);ll ans=LLONG_MAX;do{ll z=0;int v=0;for(int u:p){z+=c[v][u];v=u;}ans=min(ans,z+c[v][0]);}while(next_permutation(p.begin(),p.end()));cout<<ans<<"\\n";}',time=2500)

add('domino',23,'48. Плитка для галереи',
    'Посчитайте способы полностью покрыть прямоугольник n×m неперекрывающимися домино 1×2. Домино можно поворачивать; повороты и отражения всего покрытия считаются разными, если занятые пары клеток различаются. Выведите ответ по модулю 1000000007.',
    'Два числа n m.', '1 ≤ n ≤ 10; 1 ≤ m ≤ 1000.',
    'O(m·3^n) времени как верхняя оценка, O(3^n+2^n) памяти для переходов и двух слоёв.',
    ['Малая высота позволяет запоминать только границу между столбцами.', 'Маска обозначает клетки текущего столбца, занятые горизонтальными домино из предыдущего.', 'Заполняйте первую свободную клетку вертикальным домино внутри столбца или горизонтальным в следующий. Старт dp[0]=1; после m столбцов нужен dp[0], без выступающих домино.'],
    '''int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m;cin>>n>>m;const ll MOD=1000000007;int M=1<<n;vector<vector<int>>next(M);for(int mask=0;mask<M;mask++){function<void(int,int)>go=[&](int r,int out){if(r==n){next[mask].push_back(out);return;}if(mask>>r&1){go(r+1,out);return;}go(r+1,out|1<<r);if(r+1<n&&!(mask>>(r+1)&1))go(r+2,out);};go(0,0);}vector<ll>d(M),e(M);d[0]=1;for(int col=0;col<m;col++){fill(e.begin(),e.end(),0);for(int mask=0;mask<M;mask++)for(int out:next[mask])e[out]=(e[out]+d[mask])%MOD;swap(d,e);}cout<<d[0]<<"\\n";}''',
    'Первая свободная клетка покрыта либо вертикальным, либо горизонтальным домино; эти случаи не пересекаются и исчерпывают варианты. Маска сохраняет всю информацию, влияющую на следующий столбец.',
    ('cout<<d[0]','cout<<accumulate(d.begin(),d.end(),0LL)%MOD'),
    'int n,m;vector<bool>a;ll f(){int p=0;while(p<n*m&&a[p])p++;if(p==n*m)return 1;ll z=0;a[p]=true;if(p%m+1<m&&!a[p+1]){a[p+1]=true;z+=f();a[p+1]=false;}if(p+m<n*m&&!a[p+m]){a[p+m]=true;z+=f();a[p+m]=false;}a[p]=false;return z%1000000007;}int main(){cin>>n>>m;a.resize(n*m);cout<<f()<<"\\n";}')
